function CaseModal({item,onClose,onZoom}:{item:PortfolioCase;onClose:()=>void;onZoom:(src:string,alt:string)=>void}){return <div className="modal-shell" role="dialog" aria-modal="true" aria-labelledby="case-title" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><article className="journal"><button className="modal-close" onClick={onClose} aria-label="Close case study">Close ×</button><header className="journal-header"><p>{item.label}{item.location?` · ${item.location}`:""}</p><span>{item.number}</span><h2 id="case-title">{item.title}</h2><p className="journal-deck">{item.summary}</p>{item.disclaimer&&<p className="case-disclaimer">{item.disclaimer}</p>}</header><Gallery item={item} onZoom={onZoom}/>{item.resources&&<section className="resource-panel"><p>Project documentation</p><div>{item.resources.map(resource=><a key={resource.title} href={resource.href} target={resource.download ? undefined : "_blank"} rel={resource.download ? undefined : "noreferrer"} download={resource.download ? true : undefined}><span><strong>{resource.title}</strong><small>{resource.description}</small></span><b>{resource.actionLabel ? resource.actionLabel + " ↗" : resource.download ? "Download PDF ↓" : resource.external ? "Open link ↗" : "Read PDF ↗"}</b></a>)}</div></section>}<div className="journal-body">{item.journal.map((section,i)=><section key={section.heading}><span>{String(i+1).padStart(2,"0")}</span><div><h3>{section.heading}</h3><p>{section.text}</p></div></section>)}</div><footer className="journal-footer"><p>Olusola Ayodeji Ezekiel · Portfolio journal</p><button onClick={onClose}>Return to portfolio ↑</button></footer></article></div>}

